def separate_paren_groups(paren_string: str) -> List[str]:
    # Remove all spaces from the input string
    s = paren_string.replace(' ', '')

    groups = []
    current = []
    depth = 0

    for char in s:
        if char == '(':
            depth += 1
            current.append(char)
        elif char == ')':
            depth -= 1
            current.append(char)
            if depth == 0:
                groups.append(''.join(current))
                current = []
        else:
            # If there's any other character, and we're not at depth 0, it's inside a group
            if depth > 0:
                current.append(char)

    return groups

