def find_number_combinations():
    def has_unique_digits_across(n1, n2, n3):
        used = set()
        for n in (n1, n2, n3):
            while n:
                digit = n % 10
                if digit in used:
                    return False
                used.add(digit)
                n //= 10
        return len(used) == 9  # All nine digits 1-9 used exactly once

    results = []
    min_val = 123
    max_val = 329  # 3 * first <= 987 => first <= 329
    for first in range(min_val, max_val + 1):
        digits1 = str(first)
        if '0' in digits1 or len(set(digits1)) != 3:
            continue
        second = 2 * first
        third = 3 * first
        # Ensure second and third are 3-digit numbers
        if second < 100 or second > 999:
            continue
        if third < 100 or third > 999:
            continue
        digits2 = str(second)
        digits3 = str(third)
        if '0' in digits2 or len(set(digits2)) != 3:
            continue
        if '0' in digits3 or len(set(digits3)) != 3:
            continue
        if has_unique_digits_across(first, second, third):
            results.append((first, second, third))
    results.sort()
    return results

