def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    if m <= 0 or n <= 0:
        return 0
    # Initialize dp array of size n+1 with zeros
    dp = [0] * (n + 1)
    # For each item
    for price, value in items:
        # If price is greater than n, skip (since can't take)
        if price > n:
            continue
        # Iterate from n down to price
        for j in range(n, price - 1, -1):
            # Max of not taking or taking
            if dp[j - price] + value > dp[j]:
                dp[j] = dp[j - price] + value
    return dp[n]

