def count_partitions(n: int, k: int, x: int) -> int:
    if n is None or k is None or x is None:
        return 0
    if not isinstance(n, int) or not isinstance(k, int) or not isinstance(x, int):
        return 0
    if k < 0 or x <= 0:
        return 0
    if k == 0:
        return 1 if n == 0 else 0
    if x > n:
        return 0

    max_val = (n - (k - 1) * x) // k
    if max_val < x:
        return 0

    m = n - k * x
    if m < 0:
        return 0

    if k == 1:
        return 1

    dp = [[0] * (m + 1) for _ in range(k + 1)]
    dp[0][0] = 1

    for part_count in range(1, k + 1):
        for value in range(m + 1):
            if value < 0:
                continue
            count = 0
            for last_x in range(0, max_val + 1):
                rem = value - last_x
                if rem < 0:
                    break
                if part_count - 1 >= 0 and rem < max_val:
                    count += dp[part_count - 1][rem]
            dp[part_count][value] = count

    return dp[k][m]

