def catalan_number(n: int) -> int:
    if n < 0:
        raise ValueError("n must be non-negative")

    # Base case
    if n == 0:
        return 1

    # Dynamic programming approach
    # C(n) = sum(C(i) * C(n-1-i)) for i from 0 to n-1
    c = [0] * (n + 1)
    c[0] = 1

    for i in range(1, n + 1):
        for j in range(i):
            c[i] += c[j] * c[i - 1 - j]

    return c[n]

