def mod_inverse(a, b):
    """
    Calculate the modular multiplicative inverse of `a` modulo `b`.
    """
    if b == 0:
        return None

    # Ensure a is non-negative and less than b for simplicity, though extended Euclidean works generally
    a = a % b

    # Handle the case where a is 0 - inverse doesn't exist
    if a == 0:
        return None

    # Extended Euclidean Algorithm
    def extended_gcd(x, y):
        if x == 0:
            return (y, 0, 1)
        else:
            g, x1, y1 = extended_gcd(y % x, x)
            x = y1
            y = x1 - (y // x) * y1
            return (g, x, y)

    g, x, y = extended_gcd(a, b)

    if g != 1:
        return None
    else:
        # x may be negative, so return it modulo b
        return x % b

